/**
 * ORDEN: the three rooms. One product per room, rendered in Blender Cycles.
 *
 * Every room ships, under public/rooms/<id>/ (generated by `npm run assets`
 * from blender/renders/final/):
 *   room-beauty / product-beauty   Cycles stills with the product in place
 *   room-plate  / product-plate    the same views without the product: the
 *                                  real-time GLB is drawn over these
 *   *-depth                        depth (white = near) for the parallax
 *   probe.hdr                      light probe taken where the product stands
 * and src/config/scenes/<id>.json: both cameras (three.js coordinates, Y-up,
 * vertical fov), the product position and the depth encoding.
 */
import type { ProductId } from "./products";
import living from "./scenes/living.json";
import bedroom from "./scenes/bedroom.json";
import storage from "./scenes/storage.json";

export type RoomId = "living" | "bedroom" | "storage";
export type ShotId = "room" | "product";

export interface SceneCamera {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  /** Vertical field of view, degrees, for the 16:9 frame. */
  fov: number;
}

export interface RoomScene {
  resolution: [number, number];
  product_position: [number, number, number];
  product_rotation_y: number;
  depth: { near: number; far: number };
  cameras: { cam_room: SceneCamera; cam_product: SceneCamera; cam_room_p?: SceneCamera; cam_product_p?: SceneCamera };
}

export interface Room {
  id: RoomId;
  index: string;
  name: string;
  /** Display title of the room view. */
  title: string;
  /** Short line under the room name. */
  mood: string;
  productId: ProductId;
  scene: RoomScene;
  /** Blender exposure (stops) used for the stills: the live product matches it. */
  exposure: number;
}

const asScene = (s: unknown) => s as RoomScene;

export const ROOMS: Room[] = [
  {
    id: "living",
    index: "01",
    name: "Living",
    title: "The Living Room",
    mood: "Daylight, wool and stone.",
    productId: "coffee-table",
    scene: asScene(living),
    exposure: 0.7,
  },
  {
    id: "bedroom",
    index: "02",
    name: "Bedroom",
    title: "The Bedroom",
    mood: "Linen, low light, close at hand.",
    productId: "bedside-table",
    scene: asScene(bedroom),
    exposure: 0.85,
  },
  {
    id: "storage",
    index: "03",
    name: "Dressing",
    title: "The Dressing Room",
    mood: "A calm volume for what you keep.",
    productId: "wardrobe",
    scene: asScene(storage),
    exposure: 0.75,
  },
];

export const ROOM_MAP = Object.fromEntries(ROOMS.map((r) => [r.id, r])) as Record<RoomId, Room>;

/** landscape = the 16:9 stills; portrait = the 9:16 stills rendered for phones. */
export type Orientation = "landscape" | "portrait";

export function roomAsset(room: RoomId, shot: ShotId, kind: "beauty" | "plate" | "depth", o: Orientation = "landscape") {
  return `/rooms/${room}/${shot}${o === "portrait" ? "-p" : ""}-${kind}.webp`;
}

/** The two Blender cameras of a room for this orientation. */
export function sceneCameras(room: RoomId, o: Orientation) {
  const c = ROOM_MAP[room].scene.cameras;
  return o === "portrait" && c.cam_room_p && c.cam_product_p
    ? { room: c.cam_room_p, product: c.cam_product_p }
    : { room: c.cam_room, product: c.cam_product };
}

export const hasPortrait = (room: RoomId) => !!ROOM_MAP[room].scene.cameras.cam_room_p;

export const probeUrl = (room: RoomId) => `/rooms/${room}/probe.hdr`;

/** The stage keeps the stills' frame and covers the viewport with it. */
export const FRAME_ASPECT = 16 / 9;
export const aspectOf = (o: Orientation) => (o === "portrait" ? 9 / 16 : FRAME_ASPECT);
